/// Calculates the 64-bit CRC over `data` using reverse traversal and the ECMA-182 lookup table.
///
/// Traverses the slice in reverse order:
/// `crc = (crc >> 8) ^ CRC64_TABLE[((data[i] as u64) ^ crc) as usize & 0xFF];`
#[must_use]
pub fn calc_crc64(data: &[u8], initial_crc: u64) -> u64 {
    let mut crc = initial_crc;
    for &b in data.iter().rev() {
        let idx = ((b as u64 ^ crc) & 0xFF) as usize;
        crc = (crc >> 8) ^ CRC64_TABLE[idx];
    }
    crc
}

/// Derives an 8-byte XOR key for a given record type ID and seed byte.
///
/// Mathematical pipeline:
/// 1. `let product: u64 = MAGIC_KEY.wrapping_mul(seed as u64);`
/// 2. `let product_be: [u8; 8] = product.to_be_bytes();`
/// 3. `let initial_crc: u64 = ((seed as u64).wrapping_add(record_type as u64)) % 256;`
/// 4. `let crc = calc_crc64(&product_be, initial_crc);`
/// 5. Little-endian serialization: `crc.to_le_bytes()`
#[must_use]
pub fn derive_key(record_type: u8, seed: u8) -> [u8; 8] {
    let product: u64 = MAGIC_KEY.wrapping_mul(seed as u64);
    let product_be: [u8; 8] = product.to_be_bytes();
    let initial_crc: u64 = ((seed as u64).wrapping_add(record_type as u64)) % 256;
    let crc = calc_crc64(&product_be, initial_crc);
    crc.to_le_bytes()
}

