    #[test]
    fn test_table_boundary_entries() {
        assert_eq!(CRC64_TABLE[0], 0x0000000000000000);
        assert_eq!(CRC64_TABLE[1], 0x42F0E1EBA9EA3693);
        assert_eq!(CRC64_TABLE[255], 0x9AFCE626CE85B507);
    }

    #[test]
    fn test_table_mathematical_generator() {
        // Generate table dynamically using ECMA-182 MSB-first shifting definition
        let mut generated_table = [0u64; 256];
        for (i, entry) in generated_table.iter_mut().enumerate() {
            let mut crc = (i as u64) << 56;
            for _ in 0..8 {
                if (crc & (1u64 << 63)) != 0 {
                    crc = (crc << 1) ^ CRC64_POLY;
                } else {
                    crc <<= 1;
                }
            }
            *entry = crc;
        }

        assert_eq!(generated_table, CRC64_TABLE);
    }

