            (0, 0x0000000000000000, 0xA10A2FFD9AAC5176, [0x76, 0x51, 0xAC, 0x9A, 0xFD, 0x2F, 0x0A, 0xA1]),
            (15, 0x1111111111111010, 0x78E0F9D9B8553F25, [0x25, 0x3F, 0x55, 0xB8, 0xD9, 0xF9, 0xE0, 0x78]),
            (30, 0x2222222222222020, 0xD15FD57BF6BD9AB4, [0xB4, 0x9A, 0xBD, 0xF6, 0x7B, 0xD5, 0x5F, 0xD1]),
            (45, 0x3333333333333030, 0x309C56603A7FF80C, [0x0C, 0xF8, 0x7F, 0x3A, 0x60, 0x56, 0x9C, 0x30]),
            (60, 0x4444444444444040, 0x6CEE551D7EF094DE, [0xDE, 0x94, 0xF0, 0x7E, 0x1D, 0x55, 0xEE, 0x6C]),
            (75, 0x5555555555555050, 0xF50A2C8A1F8DE22B, [0x2B, 0xE2, 0x8D, 0x1F, 0x8A, 0x2C, 0x0A, 0xF5]),
            (90, 0x6666666666666060, 0xA2C978917269414A, [0x4A, 0x41, 0x69, 0x72, 0x91, 0x78, 0xC9, 0xA2]),
            (105, 0x7777777777777070, 0x430AFB8ABEAB23F2, [0xF2, 0x23, 0xAB, 0xBE, 0x8A, 0xFB, 0x0A, 0x43]),
            (120, 0x8888888888888080, 0x5416663F9BA709A2, [0xA2, 0x09, 0xA7, 0x9B, 0x3F, 0x66, 0x16, 0x54]),
            (135, 0x9999999999999090, 0x864DCDA3BFF13283, [0x83, 0x32, 0xF1, 0xBF, 0xA3, 0xCD, 0x4D, 0x86]),
            (150, 0xAAAAAAAAAAAAA0A0, 0x3A3F44E8099194D3, [0xD3, 0x94, 0x91, 0x09, 0xE8, 0x44, 0x3F, 0x3A]),
            (165, 0xBBBBBBBBBBBBB0B0, 0xDBFCC7F3C553F66B, [0x6B, 0xF6, 0x53, 0xC5, 0xF3, 0xC7, 0xFC, 0xDB]),
            (180, 0xCCCCCCCCCCCCC0C0, 0x878EC48E81DC9AB9, [0xB9, 0x9A, 0xDC, 0x81, 0x8E, 0xC4, 0x8E, 0x87]),
            (195, 0xDDDDDDDDDDDDD0D0, 0x1E6ABD19E0A1EC4C, [0x4C, 0xEC, 0xA1, 0xE0, 0x19, 0xBD, 0x6A, 0x1E]),
            (210, 0xEEEEEEEEEEEEE0E0, 0x49A9E9028D454F2D, [0x2D, 0x4F, 0x45, 0x8D, 0x02, 0xE9, 0xA9, 0x49]),
            (225, 0xFFFFFFFFFFFFF0F0, 0xA86A6A1941872D95, [0x95, 0x2D, 0x87, 0x41, 0x19, 0x6A, 0x6A, 0xA8]),
        ];

        for &(seed, expected_product, expected_crc, expected_le_bytes) in &degenerate_cases {
            let product = MAGIC_KEY.wrapping_mul(seed as u64);
            assert_eq!(
                product, expected_product,
                "Intermediate product mismatch for seed {}",
                seed
            );

            let key = derive_key(1, seed);
            assert_eq!(
                key, expected_le_bytes,
                "LE bytes mismatch for degenerate seed {}",
                seed
            );
            assert_eq!(
                u64::from_le_bytes(key),
                expected_crc,
                "CRC u64 mismatch for degenerate seed {}",
                seed
            );
        }
    }

    #[test]
    fn test_exhaustive_operational_keyspace_uniqueness() {
        // Assert that across all 57 standard record types and 256 seeds (14,592 combinations),
        // there are 0 collisions.
        let mut key_set = HashSet::with_capacity(57 * 256);
        for record_type in 1..=57u8 {
            for seed in 0..=255u8 {
                let key = derive_key(record_type, seed);
                assert!(
                    key_set.insert(key),
                    "Collision detected for record_type={} seed={}",
                    record_type,
                    seed
                );
            }
        }
        assert_eq!(key_set.len(), 57 * 256);
    }
}

//! Cyclic XOR de-scrambling and keystream application engine.
//!
//! Provides zero-allocation in-place de-scrambling (`descramble_in_place`), destination-slice
//! de-scrambling (`descramble_slice`), and allocating vector de-scrambling (`descramble_to_vec`)
//! for scrambled DJI record payloads.

use crate::crypto::crc64::derive_key;
use crate::error::FlightReaderError;

/// De-scrambles (or scrambles) `buf` in-place by cyclically applying the 8-byte `key`.
///
/// Because XOR is an involutive operation ($A \oplus K \oplus K = A$), this function
/// is self-inverse: applying it twice with the same key restores the original bytes.
///
/// Each byte `buf[i]` is mutated as `buf[i] ^= key[i % 8]`.
pub fn descramble_in_place(buf: &mut [u8], key: [u8; 8]) {
    for (i, b) in buf.iter_mut().enumerate() {
        *b ^= key[i % 8];
    }
}

/// De-scrambles (or scrambles) `src` into destination buffer `dst` using the cyclic 8-byte `key`.
///
/// Returns `Ok(())` on success.
///
/// # Errors
///
/// Returns [`FlightReaderError::BufferOverflow`] if `dst.len() < src.len()`.
pub fn descramble_slice(src: &[u8], dst: &mut [u8], key: [u8; 8]) -> Result<(), FlightReaderError> {
    if dst.len() < src.len() {
        return Err(FlightReaderError::BufferOverflow {
            required: src.len(),
            capacity: dst.len(),
        });
    }

    for (i, (&s, d)) in src.iter().zip(dst.iter_mut()).enumerate() {
        *d = s ^ key[i % 8];
    }

    Ok(())
}

/// De-scrambles (or scrambles) `src` into a newly allocated [`Vec<u8>`] using cyclic 8-byte `key`.
#[must_use]
pub fn descramble_to_vec(src: &[u8], key: [u8; 8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(src.len());
    for (i, &b) in src.iter().enumerate() {
        out.push(b ^ key[i % 8]);
    }
    out
}

/// De-scrambles a full record payload slice in-place, where `record_payload[0]` is the seed byte
/// and `record_payload[1..]` is the scrambled ciphertext.
///
/// Derives the 8-byte key from `(record_type, seed)`, de-scrambles `record_payload[1..]` in-place,
/// and returns a mutable subslice to the recovered plaintext payload (`&mut record_payload[1..]`).
///
/// # Errors
///
/// Returns [`FlightReaderError::PayloadTooShort`] if `record_payload.len() < 2`.
pub fn descramble_record_in_place(
    record_payload: &mut [u8],
    record_type: u8,
) -> Result<&mut [u8], FlightReaderError> {
    if record_payload.len() < 2 {
        return Err(FlightReaderError::PayloadTooShort {
            minimum: 2,
            available: record_payload.len(),
        });
    }

    let seed = record_payload[0];
    let key = derive_key(record_type, seed);
    descramble_in_place(&mut record_payload[1..], key);
    Ok(&mut record_payload[1..])
}

/// De-scrambles a full record payload slice into a newly allocated [`Vec<u8>`], where
/// `record_payload[0]` is the seed byte and `record_payload[1..]` is the scrambled ciphertext.
///
/// # Errors
///
/// Returns [`FlightReaderError::PayloadTooShort`] if `record_payload.len() < 2`.
pub fn descramble_record_to_vec(
    record_payload: &[u8],
    record_type: u8,
) -> Result<Vec<u8>, FlightReaderError> {
    if record_payload.len() < 2 {
        return Err(FlightReaderError::PayloadTooShort {
            minimum: 2,
            available: record_payload.len(),
        });
    }

    let seed = record_payload[0];
    let key = derive_key(record_type, seed);
    Ok(descramble_to_vec(&record_payload[1..], key))
}

