    #[test]
    fn test_boundary_payload_sizes() {
        let key = [0x5D, 0x73, 0x0A, 0x59, 0x50, 0xF5, 0x13, 0x01]; // OSD seed 42

        // 0-byte empty
        let empty: [u8; 0] = [];
        let descrambled_empty = descramble_to_vec(&empty, key);
        assert!(descrambled_empty.is_empty());

        // 1-byte payload: 0x11 ^ 0x5D = 0x4C
        let one = [0x11u8];
        let descrambled_one = descramble_to_vec(&one, key);
        assert_eq!(descrambled_one, [0x4C]);

        // 2-byte payload: [0x11, 0x22] ^ [0x5D, 0x73] = [0x4C, 0x51]
        let two = [0x11u8, 0x22];
        let descrambled_two = descramble_to_vec(&two, key);
        assert_eq!(descrambled_two, [0x4C, 0x51]);

        // 8-byte payload: exactly one key period
        let eight = [0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88];
        let expected_eight = [0x4C, 0x51, 0x39, 0x1D, 0x05, 0x93, 0x64, 0x89];
        assert_eq!(descramble_to_vec(&eight, key), expected_eight);

        // 9-byte payload: key wrap around
        let nine = [0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88, 0x99];
        let mut expected_nine = [0u8; 9];
        expected_nine[..8].copy_from_slice(&expected_eight);
        expected_nine[8] = 0x99 ^ key[0]; // 0xC4
        assert_eq!(descramble_to_vec(&nine, key), expected_nine);

        // 16-byte zeroes: emits key pattern repeated
        let zeroes = [0u8; 16];
        let mut expected_zeroes = [0u8; 16];
        expected_zeroes[..8].copy_from_slice(&key);
        expected_zeroes[8..16].copy_from_slice(&key);
        assert_eq!(descramble_to_vec(&zeroes, key), expected_zeroes);

        // 16-byte ones: emits bitwise not key pattern repeated
        let ones = [0xFFu8; 16];
        let not_key: [u8; 8] = [
            !key[0], !key[1], !key[2], !key[3], !key[4], !key[5], !key[6], !key[7],
        ];
        let mut expected_ones = [0u8; 16];
        expected_ones[..8].copy_from_slice(&not_key);
        expected_ones[8..16].copy_from_slice(&not_key);
        assert_eq!(descramble_to_vec(&ones, key), expected_ones);
    }

    #[test]
    fn test_involutive_roundtrip_all_256_seeds() {
        let record_type = 1u8;
        let original_data: Vec<u8> = (0..128u8).collect();

        for seed in 0..=255u8 {
            let key = derive_key(record_type, seed);

            // In-place double roundtrip
            let mut work = original_data.clone();
            descramble_in_place(&mut work, key);
            // Symmetrically apply key again
            descramble_in_place(&mut work, key);
            assert_eq!(
                work, original_data,
                "Involutive roundtrip failed for seed {}",
                seed
            );

            // Vector roundtrip
            let scrambled = descramble_to_vec(&original_data, key);
            let descrambled = descramble_to_vec(&scrambled, key);
            assert_eq!(
                descrambled, original_data,
                "Vec roundtrip failed for seed {}",
                seed
            );

            // Slice roundtrip
            let mut buf1 = vec![0u8; original_data.len()];
            let mut buf2 = vec![0u8; original_data.len()];
            descramble_slice(&original_data, &mut buf1, key).unwrap();
            descramble_slice(&buf1, &mut buf2, key).unwrap();
            assert_eq!(
                buf2, original_data,
                "Slice roundtrip failed for seed {}",
                seed
            );
        }
    }

    #[test]
    fn test_descramble_slice_buffer_overflow() {
        let key = [1, 2, 3, 4, 5, 6, 7, 8];
        let src = [0u8; 10];
        let mut dst = [0u8; 9]; // Smaller than src

        let result = descramble_slice(&src, &mut dst, key);
        assert_eq!(
            result,
            Err(FlightReaderError::BufferOverflow {
                required: 10,
                capacity: 9,
            })
        );
    }

    #[test]
    fn test_descramble_record_payload_too_short() {
        let mut buf_empty: [u8; 0] = [];
        assert_eq!(
            descramble_record_in_place(&mut buf_empty, 1),
            Err(FlightReaderError::PayloadTooShort {
                minimum: 2,
                available: 0,
            })
        );

        let mut buf_one = [42u8];
        assert_eq!(
            descramble_record_in_place(&mut buf_one, 1),
            Err(FlightReaderError::PayloadTooShort {
                minimum: 2,
                available: 1,
            })
        );

        assert_eq!(
            descramble_record_to_vec(&buf_one, 1),
            Err(FlightReaderError::PayloadTooShort {
                minimum: 2,
                available: 1,
            })
        );
    }
}

//! Cryptographic keystream and de-scrambling engine.
//!
//! Provides ECMA-182 reflected CRC64 lookup table key derivation and cyclic
//! XOR de-scrambling routines for scrambled DJI record payloads.

pub mod crc64;
pub mod xor;

pub use crc64::{calc_crc64, derive_key, CRC64_POLY, CRC64_TABLE, MAGIC_KEY};
pub use xor::{
    descramble_in_place, descramble_record_in_place, descramble_record_to_vec, descramble_slice,
    descramble_to_vec,
};
